CREATE TABLE campaign_exclusions(center_id TEXT NOT NULL,campaign_id TEXT NOT NULL,student_id TEXT NOT NULL,student_name TEXT NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(center_id,campaign_id,student_id),FOREIGN KEY(center_id,campaign_id) REFERENCES campaigns(center_id,id),FOREIGN KEY(center_id,student_id) REFERENCES students(center_id,id));
CREATE TRIGGER message_outcomes AFTER UPDATE OF state ON messages WHEN OLD.state!=NEW.state BEGIN UPDATE campaigns SET submitted=submitted+CASE WHEN NEW.state='accepted' THEN 1 ELSE 0 END,delivered=delivered+CASE WHEN NEW.state='delivered' THEN 1 ELSE 0 END,failed=failed+CASE WHEN NEW.state='failed' THEN 1 ELSE 0 END,unknown=unknown+CASE WHEN NEW.state='unknown' THEN 1 ELSE 0 END,skipped=skipped+CASE WHEN NEW.state='skipped' THEN 1 ELSE 0 END WHERE center_id=NEW.center_id AND id=NEW.campaign_id; END;
